/** All distinct categories in the catalog, in original ordering. */
export const CATALOG_CATEGORIES: string[] = (() => {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const e of CATALOG) {
    if (!seen.has(e.category)) {
      seen.add(e.category);
      out.push(e.category);
    }
  }
  return out;
})();
